import{_ as d,o,c as t,a0 as r}from"./chunks/framework.B9sLprCo.js";const f=JSON.parse('{"title":"Cordis 入门","description":"","frontmatter":{"editSource":"docs/cordis-primer.md"},"headers":[],"relativePath":"reference/cordis-primer.md","filePath":"reference/cordis-primer.md"}'),a={name:"reference/cordis-primer.md"};function c(i,e,s,l,n,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="cordis-入门" tabindex="-1">Cordis 入门 <a class="header-anchor" href="#cordis-入门" aria-label="Permalink to &quot;Cordis 入门&quot;">​</a></h1><p>Cordis 是 DeepSeek Harness 底层以 vendor 方式引入的插件框架。本文介绍 harness 插件作者在阅读<a href="./subsystems/core">子系统页面</a>上生成的服务/事件参考之前需要了解的 Cordis 核心概念；<a href="./../develop/cordis-tutorial/">Cordis 教程</a>则通过实践逐一讲解这些概念。vendor 源码与同步流程见 <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/vendor/README.md" target="_blank" rel="noreferrer">vendor/README.md</a>。</p><h2 id="五个核心概念" tabindex="-1">五个核心概念 <a class="header-anchor" href="#五个核心概念" aria-label="Permalink to &quot;五个核心概念&quot;">​</a></h2><ul><li><strong>插件是实现 Service 的对象。</strong> 它可以是一个带有可选 <code>inject</code> 和 <code>apply(ctx)</code> 字段的函数，也可以是一个 <code>Service</code> 子类，其生命周期由 Cordis 挂载到当前上下文中。</li><li><strong>上下文是服务的容器。</strong> 一个服务占据一个稳定的 <code>ctx.&lt;key&gt;</code>（如 <code>ctx.tools</code>、<code>ctx.llm</code>、<code>ctx.sessions</code>）；其他插件通过 key 查找服务，而非导入具体实现。</li><li><strong>通过 <code>inject</code> 声明服务依赖。</strong> 插件声明所需的服务后，会等待这些服务就绪才启动；加载顺序通过服务依赖表达，而非手动编排启动序列。</li><li><strong>类型化事件用于通信。</strong> 服务通过 TypeScript 声明合并注册事件名，然后以 <code>emit</code>、<code>waterfall</code>（瀑布式事件）、<code>parallel</code> 或 <code>serial</code> 方式分发，分别对应监听者观察、包装、并行扇出或按序执行。</li><li><strong>注册是可逆的副作用。</strong> 提示词片段、工具 schema、适配器、提供方和监听器通过 <code>ctx.effect()</code> 或 <code>ctx.on()</code> 安装，reload 和 teardown 时会按预期撤销。</li></ul><p><a id="dispatch-modes"></a></p><h2 id="分发模式" tabindex="-1">分发模式 <a class="header-anchor" href="#分发模式" aria-label="Permalink to &quot;分发模式&quot;">​</a></h2><p>每个事件具有以下分发模式之一，且只能通过对应方法分发。</p><table tabindex="0"><thead><tr><th>模式</th><th>是否 await？</th><th>分发顺序</th><th>是否有返回值？</th></tr></thead><tbody><tr><td><code>emit</code></td><td>否</td><td>监听器按注册顺序观察</td><td>否</td></tr><tr><td><code>waterfall</code></td><td>否</td><td>监听器按注册顺序观察</td><td>是</td></tr><tr><td><code>parallel</code></td><td>是</td><td>所有监听器并行观察事件</td><td>否</td></tr><tr><td><code>serial</code></td><td>是</td><td>监听器按注册顺序观察</td><td>是</td></tr></tbody></table><p>分发模式是事件公开约定的一部分。新的 harness 事件通过 <code>@mode</code> 标签记录模式，以便生成的目录可以将声明与分发调用点做交叉校验。</p><p><a id="cordis-waterfall-semantics"></a></p><h2 id="cordis-waterfall-语义" tabindex="-1">Cordis Waterfall 语义 <a class="header-anchor" href="#cordis-waterfall-语义" aria-label="Permalink to &quot;Cordis Waterfall 语义&quot;">​</a></h2><p><code>ctx.waterfall</code> 是环绕中间件。监听器接收 <code>(...args, next)</code>。调用 <code>next()</code> 会执行下游监听器；下游返回值通过 <code>next()</code> 返回当前包装层，可由该层包装后继续向外返回。不调用 <code>next()</code> 直接返回则短路。</p><p>协作式监听器通常修改一个共享的请求或决策对象，然后委托。监听器也可以选择完全替换结果，下游监听器将只看到替换后的结果。仅当监听器必须在普通注册之前运行时才使用 <code>prepend: true</code>。</p><p>对于单决策事件，短路是设计意图。策略监听器在拥有决策权时可以不调用 <code>next()</code> 直接返回，而仅做标注或观察的监听器则必须委托。</p><p><a id="loader-configuration"></a></p><h2 id="loader-配置" tabindex="-1">Loader 配置 <a class="header-anchor" href="#loader-配置" aria-label="Permalink to &quot;Loader 配置&quot;">​</a></h2><p><code>@deepseek-ai/cordis-plugin-include</code> 将 <code>!!js</code> 解析为表达式节点。Loader 在声明的注入激活后，基于该插件上下文（<code>ctx.serviceName</code>）插值条目的 <code>config</code>，并在每次挂载决策时基于 loader 上下文插值其 <code>disabled</code> 字段；Include 会保留嵌套行表达式，直到目标行激活。其余条目元数据保持字面值。由环境选择插件时，请使用 overlay。</p><h2 id="实践规则" tabindex="-1">实践规则 <a class="header-anchor" href="#实践规则" aria-label="Permalink to &quot;实践规则&quot;">​</a></h2><p>将行为封装为插件：工具流水线事件属于 <code>ctx.tools</code>，模型流式输出属于 <code>ctx.llm</code>，实时 agent（智能体）协调属于 <code>ctx.agents</code>。拦截和策略优先使用事件；直接能力调用优先使用服务方法。</p><p>每个注册都应有对应的 disposer（资源释放函数）：要么从 <code>ctx.effect()</code> 返回一个，要么使用 Cordis 提供的辅助方法自动处理。如果 teardown 顺序有要求，请将相关工作放在同一个 effect 中，以确保资源按预期顺序释放。</p>',20)])])}const m=d(a,[["render",c]]);export{f as __pageData,m as default};
